class MyErr extends Error {
  constructor(msg: string) {
    super(msg);
    this.name = "MyErr";
    Error.captureStackTrace(this, this.constructor);
  }
}
function main(): void {
  try { throw new MyErr("boom"); } catch (x: any) {
    console.log(String(x.stack).split("\n")[0], x.name, x instanceof MyErr);
  }
}
